import { z } from "zod";

export const ProtoSchema = z.object({
  polluted: z.number().int(),
});
export type Proto = z.infer<typeof ProtoSchema>;

export const PrototypeSchema = z.object({
  x: z.number().int(),
});
export type Prototype = z.infer<typeof PrototypeSchema>;

export const ConstructorSchema = z.object({
  prototype: PrototypeSchema,
});
export type Constructor = z.infer<typeof ConstructorSchema>;

export const RootSchema = z.object({
  ["__proto__"]: ProtoSchema,
  constructor: ConstructorSchema,
  toString: z.string(),
  hasOwnProperty: z.null(),
  valueOf: z.array(z.unknown()),
  __defineGetter__: z.number().int(),
});
export type Root = z.infer<typeof RootSchema>;

