  final Constructor constructor;
  final String toString_;
  final dynamic hasOwnProperty;
  final List<dynamic> valueOf;
  final int defineGetter;

  const Root({
    required this.proto,
    required this.constructor,
    required this.toString_,
    this.hasOwnProperty,
    required this.valueOf,
    required this.defineGetter,
  });

  factory Root.fromJson(Map<String, dynamic> json) => Root(
    proto: Proto.fromJson(json['__proto__'] as Map<String, dynamic>),
    constructor: Constructor.fromJson(json['constructor'] as Map<String, dynamic>),
    toString_: json['toString'] as String,
    hasOwnProperty: json['hasOwnProperty'],
    valueOf: json['valueOf'] as List<dynamic>,
    defineGetter: json['__defineGetter__'] as int,
  );

  Map<String, dynamic> toJson() => {
    '__proto__': proto.toJson(),
    'constructor': constructor.toJson(),
    'toString': toString_,
    'hasOwnProperty': hasOwnProperty,
    'valueOf': valueOf,
    '__defineGetter__': defineGetter,
  };
}

