import Foundation

struct Root: Codable {
    let proto: Proto
    let constructor: Constructor
    let toString: String
    let hasOwnProperty: JSONValue?
    let valueOf: [JSONValue]
    let defineGetter: Int

    enum CodingKeys: String, CodingKey {
        case proto = "__proto__"
        case constructor, toString, hasOwnProperty, valueOf
        case defineGetter = "__defineGetter__"
    }
}

struct Proto: Codable {
    let polluted: Int
}

struct Constructor: Codable {
    let prototype: Prototype
}

struct Prototype: Codable {
    let x: Int
}

/// Any JSON value (used where the type is unknown or mixed).
enum JSONValue: Codable {
    case string(String), number(Double), bool(Bool), object([String: JSONValue]), array([JSONValue]), null

    init(from decoder: Decoder) throws {
        let c = try decoder.singleValueContainer()
        if c.decodeNil() { self = .null }
        else if let v = try? c.decode(Bool.self) { self = .bool(v) }
        else if let v = try? c.decode(Double.self) { self = .number(v) }
        else if let v = try? c.decode(String.self) { self = .string(v) }
        else if let v = try? c.decode([JSONValue].self) { self = .array(v) }
        else { self = .object(try c.decode([String: JSONValue].self)) }
    }

    func encode(to encoder: Encoder) throws {
        var c = encoder.singleValueContainer()
        switch self {
        case .string(let v): try c.encode(v)
        case .number(let v): try c.encode(v)
        case .bool(let v): try c.encode(v)
        case .object(let v): try c.encode(v)
        case .array(let v): try c.encode(v)
        case .null: try c.encodeNil()
        }
    }
}

